static inline int mrh_ridge_predict(const float* features) {
    float score = MRH_RIDGE_INTERCEPT;
    for (int i = 0; i < MRH_RIDGE_N_FEATURES; i++)
        score += features[i] * MRH_RIDGE_COEF[i];
    return score > 0.0f ? 1 : 0;
}

